props.code:
if override_pose != "":
	return override_pose
if not was_grounded:
	if hop_ticks >= 0 and hop_ticks <= T.ANTIC_TICKS:
		return "ANTIC"   # visual only: shown at takeoff, no input delay
	return "RISE" if velocity.y < 0.0 else "FALL"
if land_ticks > 0:
	return "LAND"
if absf(velocity.x) > 8.0:
	return "SCOOT-A" if (tick / T.ticks(T.SCOOT_FRAME)) % 2 == 0 else "SCOOT-B"
if worried:
	return "WORRY"
if idle_ticks >= T.ticks(T.BORED_DELAY):
	return "BORED"

for fork in forks:
	if fork and fork.advance() == "down":
		# SFX-WARN (Kiran, 2026-10-03, after the second audition): the scrape plays once when the fork
		# over the jelly's current or next plate starts descending, if that fork is on screen at that
		# moment. Nothing plays when a shadow starts growing; the shadow alone does the warning.
		fork.announced = shadow_on_screen(fork) and fork.plate_index in [jelly_plate, jelly_plate + 1]
		if fork.announced:
			on_warning(fork)
